  'Certificaat vertrouwen?': 'Stol på dette certifikat?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Denne servers certifikat er ikke signeret af en anerkendt udsteder. Det er normalt for en selvhostet server, men det er også sådan en aflyttet forbindelse ser ud.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Sammenlign fingeraftrykket nedenfor med det, din server selv viser. Passer de, taler du med den rigtige maskine.',
  'Uitgegeven aan': 'Udstedt til',
  'Uitgegeven door': 'Udstedt af',
  'Geldig tot': 'Gyldigt til',
  'Vingerafdruk (SHA-256)': 'Fingeraftryk (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Kun netop dette certifikat betros. Udskifter serveren det senere, spørger OciDeck igen.',
  'Vertrouwen': 'Stol på',
  'Certificaat bekijken': 'Vis certifikat',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Stederne hvor du gemmer og søger i dine præsentationer — mapper på denne computer, WebDAV-servere, S3-buckets og git-repositories mellem hinanden. Træk dem i den rækkefølge, du vil: den øverste af en slags gælder som standard.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3-lagring: når du forbinder til en bucket, gemmes endpointet, bucket-navnet og din adgangsnøgle (den hemmelige nøgle sikkert i dit systems nøglering), og de præsentationer, du åbner eller gemmer, sendes til den lagringstjeneste.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git-lagring: når du forbinder til et repository, gemmes dit adgangstoken (sikkert i dit systems nøglering), og de præsentationer, du gemmer, sendes til den server som commits. En arbejdskopi af repositoryet forbliver ukrypteret på denne enhed.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Sygdomsnavne mangler for dette decks sprog. Religion, politisk overbevisning og fagforeningsudtryk genkendes, og mønstre med kontrolciffer (CPR, IBAN, pas) virker altid — men regn ikke med, at en diagnose bliver fundet.',
  'niet getest': 'ikke testet',
  'Werkte op': 'Virkede den',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Du er logget ind, men har ikke adgang her. Din adgangskode er ikke problemet — bed administratoren om rettigheder til denne mappe.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Dit token er gyldigt, men må ikke dette. Giv det flere rettigheder, eller vent, hvis forgen sætter en grænse.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Tokenet er gyldigt, men må ikke dette — giv det flere rettigheder til repositoryet.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Logget ind, men ingen adgang — din adgangskode er ikke problemet. Bed om rettigheder til denne mappe.',
  'Lexiconlicenties: wat er nog nagevraagd moet worden':
      'Leksikonlicenser: hvad der stadig skal spørges om',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Det ligner en fuld DAV-URL. Ved Nextcloud udleder OciDeck selv den sti — her hører kun serveren til.',
  'Overnemen': 'Anvend',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV er ikke sat rigtigt op — tjek serveroplysningerne under Indstillinger → Lagring.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Git-repositoryet er ikke sat rigtigt op — tjek server, ejer og repository under Indstillinger → Lagring.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Forgens servernavn findes ikke eller kan ikke slås op. Tjek server-URL\'en for en tastefejl.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Denne forge har en privat- eller LAN-adresse. Marker den som betroet intern under Indstillinger → Lagring.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forgen kan ikke nås — tjek din forbindelse og server-URL\'en.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Login til forgen mislykkedes. Tjek dit token: det skal have læseadgang til repositoryet og skriveadgang for at kunne gemme.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Ikke fundet i repositoryet — eller dit token må ikke se det.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forgen returnerede en fejl. Prøv igen senere.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Denne adresse svarer ikke som en forge. Er forge-typen under Indstillinger → Lagring rigtig?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Opsæt først en WebDAV-server under Indstillinger → Lagring.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Nødvendigt, når forgen kører på et privat- eller hjemmenetværk. Uden dette flag afviser sikkerhedstjekket en privat adresse.',
  'Vul server-URL, eigenaar en repository in':
      'Udfyld server-URL, ejer og repository',
  'de standaardbranch heet': 'standardgrenen hedder',
  'die wordt voortaan gebruikt': 'den bruges fremover',
  'de repository is nog leeg; de eerste opslag vult hem':
      'repositoryet er stadig tomt; den første gemning fylder det',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'bemærk: dette token må kun læse, så det vil mislykkes at gemme',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Login mislykkedes — tjek tokenet. Det skal have læseadgang til repositoryet og skriveadgang for at kunne gemme.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repository ikke fundet — eller dit token må ikke se det. Tjek ejer og repository-navn.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Denne adresse svarer ikke som en forge. Er den valgte forge-type rigtig?',
  'kenteken': 'nummerplade',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Der findes ingen nøgleordsliste for særlige kategorier af personoplysninger på dette decks sprog. Mønstre med kontrolciffer (CPR, IBAN, pas) virker; ord som "diagnose" eller "mistænkt" genkendes ikke.',
  'De trefwoordenlijst voor bijzondere persoonsgegevens is voor de taal van dit deck erg dun. Reken er niet op dat woorden als "diagnose" of "verdachte" gevonden worden.':
      'Nøgleordslisten for særlige kategorier af personoplysninger er meget tynd for dette decks sprog. Regn ikke med, at ord som "diagnose" eller "mistænkt" bliver fundet.',
  'Landpakketten voor identificatienummers':
      'Landepakker til identifikationsnumre',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Numre som det hollandske BSN eller det polske PESEL er landespecifikke. Hele Europa er slået til, fordi de fleste af de numre har et kontrolciffer: at slå dem til koster næsten ingen falske advarsler. IBAN, e-mail, hemmeligheder og pasfelter er uafhængige af dette og tjekkes altid.',
